using System;
using System.Collections.Generic;
using Scellecs.Morpeh;
using VContainer;

namespace ZE.MechBattle.Ecs
{
    public abstract class FeatureSystemsInstallQueue : IFeatureInstaller
    {
        // generated by ChatGPT
        public interface ISystemsOperator
        {
            void AddSystem<T>(SystemGroupOrder order)
                where T : class, ISystem;

            void AddSystemWithInterface<SystemType, InterfaceType>(SystemGroupOrder order)
                where SystemType : class, ISystem;
        }

        internal sealed class ContainerSystemsBinder : ISystemsOperator
        {
            private readonly IContainerBuilder builder;

            public ContainerSystemsBinder(IContainerBuilder builder)
            {
                this.builder = builder;
            }

            public void AddSystem<T>(SystemGroupOrder order)
                where T : class, ISystem
            {
                builder.Register<T>(Lifetime.Scoped);
            }

            public void AddSystemWithInterface<SystemType, InterfaceType>(SystemGroupOrder order)
                where SystemType : class, ISystem
            {
                builder.Register<SystemType>(Lifetime.Scoped).AsSelf().As<InterfaceType>();
            }
        }

        internal sealed class SystemsInitializer : ISystemsOperator
        {
            private readonly MorpehSystemInstallHandler resolver;

            public SystemsInitializer(IObjectResolver resolver)
            {
                this.resolver = resolver.Resolve<MorpehSystemInstallHandler>();
            }

            public void AddSystemWithInterface<SystemType, InterfaceType>(SystemGroupOrder order)
                where SystemType : class, ISystem
                => AddSystem<SystemType>(order);

            public void AddSystem<T>(SystemGroupOrder order)
                where T : class, ISystem
            {
                resolver.AddSystem<T>(order);
            }
        }




        protected abstract void Configure(ISystemsOperator installer);


        // 1. Bind systems into container to resolve dependencies
        public void InstallDependencies(IContainerBuilder builder)
        {
            Configure(new ContainerSystemsBinder(builder));
        }

        // 2. Add systems with fulfilled dependencies into ECS World
        public void Initialize(IObjectResolver resolver)
        {
            Configure(new SystemsInitializer(resolver));
        }
    }
}
